$p=[Diagnostics.Process]::new();$p.StartInfo=$psi;$p.Start()|Out-Null;$o=$p.StandardOutput.ReadToEndAsync();$e=$p.StandardError.ReadToEndAsync();$start=[DateTime]::UtcNow;$next=$start.AddSeconds(15)
while(!$p.HasExited){Start-Sleep -Milliseconds 100;if([DateTime]::UtcNow -gt $next){if(Get-Process|Where-Object {$_.ProcessName -match $games}){$p.Kill();throw 'game began own probe killed'};$next=[DateTime]::UtcNow.AddSeconds(15)};if(([DateTime]::UtcNow-$start).TotalSeconds -gt 60){$p.Kill();throw 'own probe watchdog no retry'}}
$p.WaitForExit();$o.Result|Set-Content "$out\stdout.log";$e.Result|Set-Content "$out\stderr.log";if($p.ExitCode){throw "capture prerequisite failed exit=$($p.ExitCode) no retry"};foreach($edge in @("first","selected-first","last")){if((Get-FileHash "$out\$edge.rgb32f").Hash -ne '153ac018f5dd5744cff9157661c46c469d01db6018a97c93aec2b1e2e05647f1'){throw 'raw lock'}};if($mode -eq 'replay' -and $o.Result -notmatch 'graph_launch_api_calls=241 expected=241'){throw 'actual graph count mismatch'};if($mode -eq 'eager' -and $o.Result -notmatch 'graph_launch_api_calls=0 expected=0'){throw 'eager graph mismatch'};} 'SAMEWORK_ABBA_FOUR_SLOT_RAW_PASS_CPU_STATS_PENDING'
}finally{$owner.Dispose();Remove-Item 'D:\DLSSNR-Lab\gpu.lock';'LOCK_RELEASED'}
